// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { MpaIcon } from "../icon";
import "./Alert.scss";
import { IconButton } from "../iconButton";
import { Button } from "../button";
import clsx from "clsx";
import { Pagination } from "../pagination";
import { SvgMpaIcon } from "../..";

type ContentType = {
  label?: string;
  message: string;
};
export interface AlertProps {
  /**
   * Unique identifier for the alert component
   */
  id: string;
  /**
   * Visual style variant of the alert
   * @default "white"
   */
  variant?: "white" | "colour";
  /**
   * Color scheme indicating alert type/severity
   */
  colour?: "info" | "success" | "error" | "warn" | "warn-info";
  /**
   * Adds additional left padding to side of alert component
   */
  additionalPadding?: boolean;
  /**
   * Text label for the action button (optional)
   */
  action?: string;
  /**
   * Callback function invoked when close button is clicked (optional)
   */
  onClose?: () => void;
  /**
   * Callback function for the action button (optional)
   */
  onAction?: () => void;
  /**
   * Size variant of the alert component
   * @default "small"
   */
  size?: "small" | "medium";
  /**
   * Content to display in the alert. Array enables paginated alert
   */
  content: ContentType | ContentType[];
  /**
   * Displays default semantic icon
   * @default true
   */
  showSemanticIcon?: boolean;
  /**
   * Toggle full width
   * @default false
   */
  fullWidth?: boolean;
  /**
   * Toggle banner mode
   * @default false
   */
  isBanner?: boolean;
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;
  /**
   * SVG React Component to be displayed as the leading alert close icon.
   */
   leadingIcon?: keyof typeof SvgMpaIcon | string;
  /**
   * SVG React Component to be displayed as the alert close icon.
   */
  trailingIcon?: keyof typeof SvgMpaIcon | string;

}

const Alert: React.FC<AlertProps> = ({
  id,
  variant = "white",
  colour,
  additionalPadding = false,
  onClose,
  action,
  onAction,
  size = "small",
  content,
  showSemanticIcon = true,
  fullWidth = false,
  isBanner = false,
  className,
  leadingIcon,
  trailingIcon,
}) => {
  const isSmall = size === "small";
  const isMedium = size === "medium";
  const isLarge = Array.isArray(content);
  const [page, setPage] = React.useState<number>(1);

  const getColourClassName = (
    elementClassName: string,
    classKeys?: { [key: string]: boolean }
  ) => {
    if (variant === "colour") {
      return clsx(elementClassName, {
        "alert-info": colour === "info",
        "alert-success": colour === "success",
        "alert-error": colour === "error",
        "alert-warn": colour === "warn",
        "alert-warn-info": colour ==="warn-info",
        "alert-colour": true,
        ...classKeys,
      });
    }
    return clsx(elementClassName, {
      "alert-info": colour === "info",
      "alert-success": colour === "success",
      "alert-error": colour === "error",
      "alert-warn": colour === "warn",
      "alert-warn-info": colour ==="warn-info",
      "alert-border": true,
      ...classKeys,
    });
  };

  const getIconName = () => {
    if (variant === "white" || variant === "colour") {
      switch (colour) {
        case "success":
          return "CircleCheck_Filled";
        case "error":
        case "warn":
          return "AlertTriangle_Filled";
        case "warn-info":
          return "AlertCircle_Filled"
        default:
          return "InfoCircle_Filled";
      }
    }
    return "InfoCircle_Filled";
  };

  return (
    <>
      <div className={clsx("alert-base", !!className && className)}>
        <div
          className={getColourClassName("alert-container", {
            "alert-full-width": fullWidth,
            "alert-banner": isBanner,
            "alert-additional-padding": additionalPadding
          })}
        >
          <div className="alert-top">
            <div className={clsx("alert-left", { "alert-banner": isBanner })}>
              {showSemanticIcon && (
                <div
                  className={getColourClassName("alert-icon", {
                    "align-icon": isSmall,
                  })}
                >
                {}
                {leadingIcon ? 
                  <MpaIcon iconName={leadingIcon} size={28} />
                   :
                  <MpaIcon iconName={getIconName()} size={28} />
                  }
                </div>
              )}
              <div className={getColourClassName("alert-content")}>
                {Array.isArray(content)
                  ? !!content.length && (
                    <>
                      {content[page - 1].label && (
                        <div className="alert-title">
                          {content[page - 1].label}
                        </div>
                      )}
                      {content[page - 1].message}
                    </>
                  )
                  : content && (
                    <>
                      {content.label && (
                        <div className="alert-title">{content.label}</div>
                      )}
                      {content.message}
                    </>
                  )}
              </div>
            </div>
            <div className={clsx("alert-right", { "alert-banner": isBanner })}>
              {action && (
                <div
                  className={clsx("alert-action", {
                    "align-action": isMedium && !isLarge,
                  })}
                >
                  <Button
                    id={id}
                    btnType="text"
                    onClick={onAction}
                    className={getColourClassName("action-button")}
                    label={action}
                  ></Button>
                </div>
              )}
              {onClose && (
                <div
                  className={clsx("alert-close", {
                    "close-divider": isSmall && !isBanner,
                    "align-close": isMedium || isLarge,
                  })}
                >
                  {trailingIcon ? <IconButton
                    id={id}
                    className="close-icon-button"
                    icon={trailingIcon}
                    btnType="standard"
                    size="large"
                    onClick={onClose}
                  /> :
                    <IconButton
                      id={id}
                      className="close-icon-button"
                      icon="Cross_SGDS"
                      btnType="standard"
                      size="large"
                      onClick={onClose}
                    />
                  }
                </div>
              )}
            </div>
          </div>
          {content && Array.isArray(content) && !!content.length && (
            <div className="alert-pagination">
              <Pagination
                id={id}
                type="responsive"
                totalPages={content.length}
                pageInfoLabel="/"
                onPageChange={setPage}
                onItemsPerPageChange={() => { }}
              />
            </div>
          )}
        </div>

      </div>


    </>

  );
};

export default Alert;
